//! The trigger box's scheduling core in Rust (generated by Vantage with the project's sync plan): the same
//! algorithm and the same integer arithmetic as `trigger_core.c`, tick for tick (Vantage's host check compares the
//! two). `no_std`, no dependencies: the RP2040 firmware and the host simulation both use it.
//!
//! Ticks are the board's timer counts as a 64-bit count that never wraps. The plan's times are nominal ticks x 2^24.
//! The PPS discipline is a least-squares line through the last 16 PPS captures against their second numbers: its
//! slope is the crystal's frequency (eps, x 2^40), its value at the newest second that second's anchor. Lock: the
//! first PPS re-anchors the schedule, the second measures the crystal, three in a row within `lock_ticks` (and four
//! in the fit) lock it; without PPS for 1.25 s the anchor advances on its own (holdover). Only trigger pulses come
//! out of this.
#![cfg_attr(not(test), no_std)]

pub const MAX_LINES: usize = 8;
pub const Q: u32 = 24;
pub const EQ: u32 = 40;
const ONE_Q: i64 = 1 << Q;
const HALF_Q: i64 = 1 << (Q - 1);
const EPS_MAX: i64 = 1 << (EQ - 10);
pub const WIN: usize = 16;
pub const WIN_SPAN: i64 = 64;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum State {
    Free = 0,
    Locking = 1,
    Locked = 2,
    Holdover = 3,
}

impl State {
    pub fn name(self) -> &'static str {
        match self {
            State::Free => "free",
            State::Locking => "locking",
            State::Locked => "locked",
            State::Holdover => "holdover",
        }
    }
}

#[derive(Clone, Copy, Debug)]
pub struct Line {
    pub bursts: u32,
    pub burst: u32,
    pub phase_q: u64,
    pub period_q: u64,
    pub spacing_q: u64,
    pub width: u32,
    pub mask: u32,
}

#[derive(Clone, Copy, Debug)]
pub struct Plan {
    pub hz: u32,
    pub lines: &'static [Line],
    pub lock_ticks: u32,
    pub step_ticks: u32,
    pub min_gap: u32,
}

#[derive(Clone, Copy, Debug, Default)]
pub struct LineState {
    pub sec: i64,
    pub k: u32,
    pub rise: i64,
    pub fall: i64,
    pub done_fall: i64,
    pub phase: u8, // 0 fetched (rise to come), 1 high (fall to come), 2 idle
}

pub struct Core {
    pub plan: Plan,
    pub anchor: i64,
    pub anchor_frac: u32,
    pub anchor_sec: i64,
    pub eps: i64,
    pub state: State,
    pub good: i32,
    pub win_sec: [i64; WIN],
    pub win_c: [i64; WIN],
    pub n_win: usize,
    pub i_win: usize,
    pub last_out: i64,
    pub last_pps: i64,
    pub pending: i64,
    pub resid: i64,
    pub pps: u32,
    pub missed: u32,
    pub steps: u32,
    pub outliers: u32,
    pub out: u32,
    pub ln: [LineState; MAX_LINES],
}

fn fdiv_q(x: i64) -> i64 {
    if x >= 0 {
        x >> Q
    } else {
        -((-x + ONE_Q - 1) >> Q)
    }
}

impl Core {
    pub fn new(plan: Plan, now: i64) -> Core {
        let mut ln = [LineState::default(); MAX_LINES];
        for l in ln.iter_mut() {
            l.done_fall = now;
            l.phase = 2;
        }
        Core {
            plan,
            anchor: now + (plan.hz / 10) as i64,
            anchor_frac: 0,
            anchor_sec: 0,
            eps: 0,
            state: State::Free,
            good: 0,
            win_sec: [0; WIN],
            win_c: [0; WIN],
            n_win: 0,
            i_win: 0,
            last_out: now,
            last_pps: -1,
            pending: -1,
            resid: 0,
            pps: 0,
            missed: 0,
            steps: 0,
            outliers: 0,
            out: 0,
            ln,
        }
    }

    pub fn second_q(&self) -> i64 {
        let hz = self.plan.hz as i64;
        hz * ONE_Q + (hz * self.eps) / 65536
    }

    pub fn ppb(&self) -> i32 {
        ((self.eps * 1_000_000_000) / (1i64 << EQ)) as i32
    }

    fn set_anchor(&mut self, rel: i64) {
        let whole = fdiv_q(rel);
        self.anchor += whole;
        self.anchor_frac = (rel - whole * ONE_Q) as u32;
    }

    pub fn pulse_tick(&self, line: usize, sec: i64, k: u32) -> i64 {
        let l = &self.plan.lines[line];
        let (b, j) = (k / l.burst, k % l.burst);
        let off = (l.phase_q + b as u64 * l.period_q + j as u64 * l.spacing_q) as i64;
        let corr = ((off >> Q) * self.eps) / 65536;
        let rel = (sec - self.anchor_sec) * self.second_q() + off + corr + self.anchor_frac as i64;
        self.anchor + fdiv_q(rel + HALF_Q)
    }

    /// The line's next pulse (rise, fall), for one timer channel per line.
    pub fn line_next(&mut self, line: usize) -> (i64, i64) {
        let l = self.plan.lines[line];
        let n = l.bursts * l.burst;
        let floor = self.ln[line].done_fall + self.plan.min_gap as i64;
        loop {
            let (sec, k) = (self.ln[line].sec, self.ln[line].k);
            let t = self.pulse_tick(line, sec, k);
            let s = &mut self.ln[line];
            s.k += 1;
            if s.k >= n {
                s.k = 0;
                s.sec += 1;
            }
            if t > floor {
                s.rise = t;
                s.fall = t + l.width as i64;
                s.phase = 0;
                return (s.rise, s.fall);
            }
        }
    }

    pub fn line_started(&mut self, line: usize) {
        self.ln[line].phase = 1;
    }

    pub fn line_ended(&mut self, line: usize) {
        let s = &mut self.ln[line];
        if s.fall > s.done_fall {
            s.done_fall = s.fall;
        }
        s.phase = 2;
    }

    fn step_to(&mut self, c: i64) {
        self.anchor = c;
        self.anchor_frac = 0;
        self.anchor_sec += 1;
        let mut floor = c - self.plan.min_gap as i64 - 1;
        if self.last_out > floor {
            floor = self.last_out;
        }
        let sec = self.anchor_sec - 1;
        for s in self.ln.iter_mut().take(self.plan.lines.len()) {
            if s.phase == 0 {
                s.phase = 2;
            }
            if s.done_fall < floor {
                s.done_fall = floor;
            }
            s.sec = sec;
            s.k = 0;
        }
        self.good = 0;
        self.n_win = 0;
        self.state = State::Locking;
    }

    fn win_add(&mut self, sec: i64, c: i64) {
        let mut i = (self.i_win + self.n_win) % WIN;
        if self.n_win == WIN {
            self.i_win = (self.i_win + 1) % WIN;
            i = (self.i_win + WIN - 1) % WIN;
        } else {
            self.n_win += 1;
        }
        self.win_sec[i] = sec;
        self.win_c[i] = c;
    }

    /// The least-squares line through the window's captures: slope = frequency, value at the newest = anchor.
    fn fit(&mut self) {
        let hz = self.plan.hz as i64;
        let last = (self.i_win + self.n_win - 1) % WIN;
        let (last_s, last_c) = (self.win_sec[last], self.win_c[last]);
        let (mut n, mut sx, mut sxx, mut sy, mut sxy) = (0i64, 0i64, 0i64, 0i64, 0i64);
        for j in 0..self.n_win {
            let i = (self.i_win + j) % WIN;
            let x = self.win_sec[i] - last_s;
            if x < -WIN_SPAN {
                continue;
            }
            let y = self.win_c[i] - last_c - x * hz;
            n += 1;
            sx += x;
            sxx += x * x;
            sy += y;
            sxy += x * y;
        }
        let den = n * sxx - sx * sx;
        if n < 2 || den == 0 {
            return;
        }
        let num = n * sxy - sx * sy;
        let b_q = (num / den) * ONE_Q + ((num % den) * ONE_Q) / den;
        let a_q = (sy * ONE_Q - b_q * sx) / n;
        self.eps = (b_q * 65536 / hz).clamp(-EPS_MAX, EPS_MAX);
        self.anchor = last_c;
        self.anchor_frac = 0;
        self.set_anchor(a_q);
    }

    /// A PPS edge captured at tick c; true when the schedule stepped.
    pub fn on_pps(&mut self, c: i64) -> bool {
        let sq = self.second_q();
        let rq = (c - self.anchor) * ONE_Q - self.anchor_frac as i64 - sq;
        let step_q = self.plan.step_ticks as i64 * ONE_Q;
        let r = fdiv_q(rq + HALF_Q);
        self.pps += 1;
        self.resid = r;
        if self.state == State::Free || self.last_pps < 0 {
            self.step_to(c);
            self.win_add(self.anchor_sec, c);
            self.last_pps = c;
            self.pending = -1;
            return true;
        }
        if (rq > step_q || rq < -step_q) && self.n_win >= 2 {
            if self.pending >= 0 && (c - self.pending - fdiv_q(sq + HALF_Q)).abs() <= self.plan.step_ticks as i64 {
                let p = self.pending;
                self.step_to(c);
                self.win_add(self.anchor_sec - 1, p);
                self.win_add(self.anchor_sec, c);
                self.fit();
                self.steps += 1;
                self.last_pps = c;
                self.pending = -1;
                return true;
            }
            self.pending = c;
            self.outliers += 1;
            return false;
        }
        self.pending = -1;
        let gap = fdiv_q((c - self.anchor) * ONE_Q - self.anchor_frac as i64 + sq / 2);
        let secs = (gap / fdiv_q(sq)).max(1);
        self.anchor_sec += secs;
        self.win_add(self.anchor_sec, c);
        self.fit();
        if self.state == State::Holdover {
            self.state = State::Locking;
        }
        self.good = if r.abs() <= self.plan.lock_ticks as i64 { self.good + 1 } else { 0 };
        if self.good >= 3 && self.n_win >= 4 {
            self.state = State::Locked;
        }
        self.last_pps = c;
        false
    }

    pub fn poll(&mut self, now: i64) {
        loop {
            let sq = self.second_q();
            let late = self.anchor + fdiv_q(self.anchor_frac as i64 + sq + sq / 4);
            if now <= late {
                return;
            }
            self.set_anchor(self.anchor_frac as i64 + sq);
            self.anchor_sec += 1;
            if self.state != State::Free {
                self.missed += 1;
            }
            if self.state == State::Locked {
                self.state = State::Holdover;
            }
            self.good = 0;
        }
    }

    /// All lines merged (one port): the next edge's tick and the output state from it on.
    pub fn next_edge(&mut self) -> (i64, u32) {
        let n = self.plan.lines.len();
        if n == 0 {
            let t = self.anchor + fdiv_q(self.anchor_frac as i64 + self.second_q());
            return (t, self.out);
        }
        let mut best = i64::MAX;
        for i in 0..n {
            if self.ln[i].phase == 2 {
                self.line_next(i);
            }
            let s = &self.ln[i];
            let t = if s.phase == 0 { s.rise } else { s.fall };
            if t < best {
                best = t;
            }
        }
        for i in 0..n {
            let s = self.ln[i];
            let t = if s.phase == 0 { s.rise } else { s.fall };
            if t - best < self.plan.min_gap as i64 || t == best {
                if s.phase == 0 {
                    self.out |= self.plan.lines[i].mask;
                    self.ln[i].phase = 1;
                } else {
                    self.out &= !self.plan.lines[i].mask;
                    self.line_ended(i);
                }
            }
        }
        self.last_out = best;
        (best, self.out)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    // 10 Hz and 30 Hz lines on a 125 MHz timer, phases 17.1364 ms and 0.5 ms (from a typical sync plan)
    const LINES: [Line; 2] = [
        Line { bursts: 30, burst: 1, phase_q: 35_939_009_655_766, period_q: 69_905_066_666_666, spacing_q: 0, width: 12_500, mask: 1 },
        Line { bursts: 10, burst: 1, phase_q: 1_048_576_000_000, period_q: 209_715_200_000_000, spacing_q: 0, width: 12_500, mask: 2 },
    ];
    const PLAN: Plan = Plan { hz: 125_000_000, lines: &LINES, lock_ticks: 250, step_ticks: 6_250, min_gap: 3 };

    #[test]
    fn exact_clock_puts_every_pulse_on_its_tick() {
        let mut c = Core::new(PLAN, 0);
        c.on_pps(125_000_000);
        for s in 2..6 {
            c.on_pps(s * 125_000_000);
        }
        assert_eq!(c.state, State::Locked);
        assert_eq!(c.eps, 0);
        // line 1 pulse 3 of the second starting at 5 s: 5 s + 0.5 ms + 300 ms
        assert_eq!(c.pulse_tick(1, c.anchor_sec, 3), 5 * 125_000_000 + 62_500 + 37_500_000);
    }

    #[test]
    fn fast_crystal_is_measured_and_tracked() {
        let mut c = Core::new(PLAN, 0);
        let per = 125_003_750i64; // +30 ppm
        for s in 1..20 {
            c.on_pps(s * per);
        }
        assert_eq!(c.state, State::Locked);
        assert!((c.ppb() - 30_000).abs() < 5, "ppb {}", c.ppb());
    }

    #[test]
    fn holdover_and_merged_edges_stay_ordered() {
        let mut c = Core::new(PLAN, 0);
        for s in 1..6 {
            c.on_pps(s * 125_000_000);
        }
        let mut last = 0;
        for _ in 0..800 {
            let (t, _) = c.next_edge();
            assert!(t > last);
            last = t;
            c.poll(t);
        }
        assert_eq!(c.state, State::Holdover);
    }
}
